def solve(g):
    h=len(g); w=len(g[0])
    bg=0
    rows=[r for r in range(h) if any(g[r][c]!=bg for c in range(w))]
    bot=max(rows)
    out=[[bg]*w for _ in range(h)]
    for r in rows:
        for c in range(w):
            if g[r][c]!=bg and c-(bot-r)>=0:
                out[r][c-(bot-r)]=g[r][c]
    return out
